oa_status": "green", "oa_url": "https://www.preprints.org/frontend/manuscript/df8776de90db013236d14d920ade3c66/download_pub", "any_repository_has_fulltext": true}, "primary_location": {"id": "doi:10.20944/preprints202603.1694.v1", "doi": "https://doi.org/10.20944/preprints202603.1694.v1", "is_oa": true, "landing_page_url": "https://doi.org/10.20944/preprints202603.1694.v1", "pdf_url": "https://www.preprints.org/frontend/manuscript/df8776de90db013236d14d920ade3c66/download_pub", "source": {"id": "https://openalex.org/S6309402219", "display_name": "Preprints.org", "issn_l": null, "issn": null, "is_oa": true, "is_in_doaj": false, "is_core": false, "listed_in": [], "host_organization": null, "host_organization_name": null, "host_organization_lineage": ["https://openalex.org/P4310310987"], "host_organization_lineage_names": ["Multidisciplinary Digital Publishing Institute"], "type": "repository"}, "license": "cc-by", "license_id": "https://openalex.org/licenses/cc-by", "version": "acceptedVersion", "is_accepted": true, "is_published": false, "raw_source_name": null, "raw_type": "posted-content"}, "abstract": "The history of artificial intelligence for scientific discovery is not a two year story about chatbots learning to write papers. It is a sixty year story about science repeatedly handing its bottlenecks to machines—first inference, then search, then measurement, then the full workflow—only to discover that each delegation solves one problem and exposes a harder one underneath. This paper traces that history from DENDRAL (1965) through the construction of open scholarly infrastructure (arXiv, Google Scholar, ORCID), the oracle breakthroughs of AlphaFold, and the current era of LLM driven autonomous research agents. Three interlocking threads are followed including AI as research instrument, AI for research infrastructure, and the reshaping of scholarly profiles and incentives by machine readable metrics. The central tension throughout is between automation and augmentation between building systems that replace human researchers and tools that amplify human creativity and judgement. The paper presents that the most consequential development is not any single tool but the emergence of an interconnected ecosystem where AI agents, preprint platforms, open source codebases, and citation infrastructure form a feedback loop that is fundamentally restructuring who can do science, how fast discoveries propagate, and what counts as a valid scientific contribution."}]", "excerpt_truncated": true, "source_sha256": "3a2794d38861c9d244f6d1625f94785fb66045bd6b703fb75c7b4f09b69fcc05", "verification_required": true, "topic_domain": "unassigned_problem", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.48550/arxiv.2601.06978", "doi:10.20944/preprints202603.1694.v1", "openalex:W7123484531"], "source_candidates": ["https://doi.org/10.48550/arxiv.2601.06978", "https://gala.gre.ac.uk/id/eprint/52284/7/52284%20LE%20HOUX_Benchmarking_Autonomy_In_Scientific_Experiments_%28OA%20PREPRINT%29_2026.pdf", "https://doi.org/10.20944/preprints202603.1694.v1"], "source_candidate_identities": {}}

